package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeFieldType;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DateTimeFormatter_parseInto_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void parseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd").getFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void parseInto_StandardDate_ReturnsNewPosition() {
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd").getFormatter();
        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "2023-05-20";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // "yyyy-MM-dd" is 10 chars
        assertEquals(10, newPos);
        assertEquals(2023, instant.getYear());
        assertEquals(5, instant.getMonthOfYear());
        assertEquals(20, instant.getDayOfMonth());
    }

    @Test
    public void parseInto_WithTimeAndZone_UpdatesInstantCorrectly() {
        // Pattern that includes offset to trigger the bucket.getOffsetInteger() branch
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd HH:mm Z").getFormatter();
        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "2023-05-20 10:30 +0500";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        assertEquals(19, newPos);
        assertEquals(2023, instant.getYear());
        assertEquals(5, instant.getMonthOfYear());
        assertEquals(20, instant.getDayOfMonth());
        assertEquals(10, instant.getHourOfDay());
        assertEquals(30, instant.getMinuteOfHour());
        // Check if zone was updated by offset
        assertEquals("+05:00", instant.getZone().toString());
    }

    @Test
    public void parseInto_WithFixedZone_RespectsFormatterZone() {
        // Test the branch: if (iZone != null) { instant.setZone(iZone); }
        DateTimeZone fixedZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withZone(fixedZone)
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "2023-01-01";

        formatter.parseInto(instant, text, 0);

        assertEquals(fixedZone, instant.getZone());
        assertEquals(2023, instant.getYear());
    }

    @Test
    public void parseInto_WithPivotYear_UsesPivotYearInBucket() {
        // Testing the use of iPivotYear in the bucket constructor
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yy-MM-dd")
                .withPivotYear(2000)
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "23-05-20"; // 23 should be interpreted relative to pivot

        formatter.parseInto(instant, text, 0);

        assertEquals(2023, instant.getYear());
    }

    @Test
    public void parseInto_WithLocale_ParsesMonthNames() {
        // Testing the iLocale usage via month names
        DateTimeFormatter formatter = DateTimeFormat.forPattern("dd MMM yyyy")
                .withLocale(Locale.FRENCH)
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "20 mai 2023";

        formatter.parseInto(instant, text, 0);

        assertEquals(2023, instant.getYear());
        assertEquals(5, instant.getMonthOfYear());
        assertEquals(20, instant.getDayOfMonth());
    }

    @Test
    public void parseInto_WithChronology_UsesProvidedChronology() {
        // Testing the selectChronology(chrono) branch
        Chronology iso = org.joda.time.impl.ISOChronology.getInstanceUTC();
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withChronology(iso)
                .getFormatter();

        MutableDateTime instant = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        String text = "2023-05-20";

        formatter.parseInto(instant, text, 0);

        assertEquals(iso, instant.getChronology());
        assertEquals(2023, instant.getYear());
    }
}
